public class TimesTableRow {

    public static String multiplicationRow(int n, int upTo) {
        StringBuilder row = new StringBuilder();
        for (int i = 1; i <= upTo; i++) {
            if (i > 1) {
                row.append(" ");
            }
            row.append(n * i);
        }
        return row.toString();
    }
}
